def _ul(items): return "<ul>" + "".join(f"<li>{i}</li>" for i in items) + "</ul>"

def privacy(L, U, EMAIL, ADDR, sp_table, R):
    p = P[L]; h = p["h"]; f = dict(dpa=U("dpa"), sec=U("security"), email=EMAIL, m=R["msg_default_days"], g=R["guest_contact_days"], d=R["deletion_days"]); f["del"] = U("delacc")
    fm = lambda s: s.format(**f)
    sec = [p["role"], _ul(p["collect"]), _ul(p["use"]) + f'<p>{p["nosell"]}</p>', f'<p>{p["bases"]}</p>', f'<p>{p["share"]}</p>' + sp_table(L) + f'<p>{p["law"]}</p>',
           f'<p>{p["transfer"]}</p>', _ul([fm(x) for x in p["keep"]]), f'<p>{fm(p["security"])}</p>', "".join(f"<p>{fm(x)}</p>" for x in p["rights"]),
           f'<p>{p["cookies"]}</p>', f'<p>{p["wa"]}</p>', f'<p>{p["kids"]}</p>', f'<p>{p["changes"]}</p>',
           _ul([f'{p["email"]}: <a href="mailto:{EMAIL}">{EMAIL}</a>', f'{p["addr"]}: {ADDR}'])]
    sec[0] = f"<p>{fm(sec[0])}</p>"
    return f'<p>{p["intro"]}</p>' + "".join(f"<h2>{i+1}. {h[i]}</h2>{s}" for i, s in enumerate(sec))

def terms(L, U, EMAIL, ADDR, Q):
    t = T[L]; h = t["h"]; sepq = "." if L in ("es", "it", "pt") else " "
    q = {k: v.replace(",", sepq) for k, v in Q.items()}
    f = dict(pricing=U("pricing"), dpa=U("dpa"), privacy=U("privacy"), email=EMAIL, qs=q["starter"], qp=q["pro"], qg=q["growth"])
    fm = lambda s: s.format(**f)
    sec = [f'<p>{t["service"]}</p>', f'<p>{t["account"]}</p>', _ul([fm(x) for x in t["pay"]]), f'<p>{fm(t["quota"])}</p>', f'<p>{fm(t["cancel"])}</p>',
           f'<p>{t["aup_p"]}</p>' + _ul(t["aup"]), f'<p>{fm(t["guest"])}</p>', f'<p>{t["ai"]}</p>', f'<p>{t["channels"]}</p>', f'<p>{fm(t["data"])}</p>',
           f'<p>{t["avail"]}</p>', f'<p>{t["ip"]}</p>', f'<p>{t["liab"]}</p>', f'<p>{t["lawtxt"]}</p>', f'<p>{t["changes"]}</p>',
           _ul([f'{P[L]["email"]}: <a href="mailto:{EMAIL}">{EMAIL}</a>', f'{P[L]["addr"]}: {ADDR}'])]
    return f'<p>{t["intro"]}</p>' + "".join(f"<h2>{i+1}. {h[i]}</h2>{s}" for i, s in enumerate(sec))
